#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
enum class Stage { Approach, Act, Apply, Done };
class Lesson {
    Stage stage_=Stage::Approach;
public:
    bool reachedPractice(){
        if(stage_!=Stage::Approach)return false;
        stage_=Stage::Act;return true;
    }
    bool succeeded(bool inNewContext){
        if(stage_==Stage::Act && !inNewContext){stage_=Stage::Apply;return true;}
        if(stage_==Stage::Apply && inNewContext){stage_=Stage::Done;return true;}
        return false;
    }
    Stage stage()const{return stage_;}
};
int main(){
    Lesson l;assert(!l.succeeded(false));assert(!l.succeeded(true));
    assert(l.reachedPractice());assert(!l.reachedPractice());
    assert(!l.succeeded(true));assert(l.succeeded(false));
    assert(!l.succeeded(false));assert(l.stage()==Stage::Apply);
    assert(l.succeeded(true));assert(l.stage()==Stage::Done);
    assert(!l.succeeded(true));
    std::cout<<"tutorial progression tests passed\n";
}
